import { readFile, writeFile } from "node:fs/promises"
import { fileURLToPath } from "node:url"
import path from "node:path"

const directory = path.dirname(fileURLToPath(import.meta.url))
const root = path.resolve(directory, "../..")
const inputPath = path.join(directory, "providers.json")
const outputPath = path.join(root, "model_settings.generated.v")
const docsPath = path.join(root, "docs/PROVIDERS.md")
const openapiPath = path.join(root, "docs/openapi.yaml")
const selected = JSON.parse(await readFile(inputPath, "utf8"))

function validate() {
  if (!/^[a-f0-9]{40}$/.test(selected.source?.commit ?? "")) {
    throw new Error("provider catalog must pin a full Models.dev commit SHA")
  }
  if (selected.source?.repository !== "https://github.com/anomalyco/models.dev") {
    throw new Error("unexpected provider catalog source")
  }
  if (!Array.isArray(selected.providers) || selected.providers.length < 200) {
    throw new Error("provider catalog must retain at least 200 endpoint presets")
  }
  if (selected.providers.filter((provider) => provider.source === "models.dev").length < 150) {
    throw new Error("expected at least 150 validated Models.dev OpenAI-compatible presets")
  }
  const ids = new Set()
  for (const provider of selected.providers) {
    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(provider.id)) {
      throw new Error(`invalid provider ID: ${provider.id}`)
    }
    if (ids.has(provider.id)) throw new Error(`duplicate provider ID: ${provider.id}`)
    ids.add(provider.id)
    if (!provider.name || !provider.protocol || !provider.description || !provider.api) {
      throw new Error(`incomplete provider metadata: ${provider.id}`)
    }
    if (provider.requires_api_key && !/^[A-Z0-9_]+$/.test(provider.environment_key)) {
      throw new Error(`invalid environment variable for ${provider.id}`)
    }
    if (provider.source === "models.dev") {
      if (provider.protocol !== "openai-compatible") {
        throw new Error(`Models.dev compatible preset has a non-compatible protocol: ${provider.id}`)
      }
      if (provider.models_dev_source !== `providers/${provider.id}/provider.toml`) {
        throw new Error(`unexpected Models.dev path for ${provider.id}`)
      }
      if (!provider.documentation_url) throw new Error(`missing provider documentation: ${provider.id}`)
    }
    const api = new URL(provider.api)
    if (api.protocol !== "https:" && !(api.protocol === "http:" && ["127.0.0.1", "localhost", "[::1]"].includes(api.hostname))) {
      throw new Error(`invalid API URL protocol for ${provider.id}`)
    }
    if (api.username || api.password || api.search || api.hash || /[{}$]/.test(provider.api)) {
      throw new Error(`unresolved or unsafe API URL for ${provider.id}`)
    }
    if (provider.documentation_url) {
      const docs = new URL(provider.documentation_url)
      if (docs.protocol !== "https:" || docs.username || docs.password) {
        throw new Error(`invalid documentation URL for ${provider.id}`)
      }
    }
  }
}

function vString(value) {
  return `'${value.replaceAll("\\", "\\\\").replaceAll("'", "\\'").replaceAll("$", "\\$")}'`
}

function renderV() {
  const providers = [...selected.providers].sort((a, b) => a.id.localeCompare(b.id))
  const idParts = providers.map((provider) => vString(provider.id))
  const idLines = []
  let idLine = "const supported_model_providers = ["
  for (const [index, id] of idParts.entries()) {
    const part = `${id}${index < idParts.length - 1 ? ", " : ""}`
    // The pinned V formatter wraps these two boundaries one item earlier than
    // the generic width threshold. Keep the generated declaration stable.
    const formatterBoundary =
      (id === "'oci'" && idLine.endsWith("'nvidia', ")) ||
      (id === "'tinfoil'" && idLine.endsWith("'the-grid-ai', "))
    if (idLine.length + part.length > 103 || formatterBoundary) {
      idLines.push(idLine.trimEnd())
      idLine = `\t${part}`
    } else {
      idLine += part
    }
  }
  idLines.push(`${idLine}]`)
  const entries = providers.map((provider) => `\t\tModelProviderInfo{ id: ${vString(provider.id)}, name: ${vString(provider.name)}, description: ${vString(provider.description)}, protocol: ${vString(provider.protocol)}, base_url: ${vString(provider.api)}, environment_key: ${vString(provider.environment_key)}, documentation_url: ${vString(provider.documentation_url)}, requires_api_key: ${provider.requires_api_key} },`).join("\n")
  return `// Generated by tools/provider-catalog/generate.mjs. Do not edit by hand.\n// Models.dev data: ${selected.source.repository}/tree/${selected.source.commit}\nmodule main\n\n${idLines.join("\n")}\n\nfn model_provider_catalog() []ModelProviderInfo {\n\treturn [\n${entries}\n\t]\n}\n`
}

function renderDocs() {
  const providers = [...selected.providers].sort((a, b) => a.name.localeCompare(b.name))
  const rows = providers.map((provider) => {
    const docs = provider.documentation_url ? `[Documentation](${provider.documentation_url})` : "—"
    const credential = provider.requires_api_key ? provider.environment_key : "Not required by preset"
    return `| ${provider.name} | ${provider.id} | ${provider.protocol} | ${provider.api} | ${credential} | ${docs} |`
  }).join("\n")
  const modeldevCount = providers.filter((provider) => provider.source === "models.dev").length
  return `<!-- Generated by tools/provider-catalog/generate.mjs. Do not edit the provider table by hand. -->\n# Model providers\n\nVeasel ships ${providers.length} provider presets in the V binary. This count describes endpoint presets, not independent SDKs or equivalent feature coverage. Four protocol adapters currently power them: OpenAI Chat Completions, OpenAI Responses, Anthropic Messages, and Google Gemini. The ${modeldevCount} entries sourced from Models.dev use Veasel's shared OpenAI-compatible Chat Completions transport; provider-specific SDK features, authentication schemes, and model capabilities are not implied. The OpenAI Responses preset and Meta Model API use the Responses transport. OpenAI reasoning parameters are sent only for reasoning-capable model families; Meta uses high reasoning with automatic summaries and stateless encrypted reasoning replay for tool loops.\n\nThe TUI fetches this catalog from the local Veasel server. Use /connect (or press s / /models for full settings) to pick a provider, paste an API key, and choose a model. Veasel saves the key locally for future use; environment variables remain an optional alternative and lose to a saved profile key for the same provider. The provider picker cycles with Tab through all, configured, loopback-local, specialized-API, and OpenAI-compatible presets; counts and credential status come from the server catalog and active configuration. Settings collects the endpoint and credential before model discovery, then checks the provider's model-list endpoint and lets you choose a returned ID or enter one manually. A newly entered key is sent to the local server in a POST body for discovery and is saved when you choose a model. The output-token budget is filled in from /models or Ctrl+O; /connect skips straight to model selection after credentials. Zero selects Veasel's 4,096-token default, except Meta, where zero omits \`max_output_tokens\` so Meta applies its own limit. Discovery does not create a profile, issue a model prompt, or start generation.\n\nModels.dev entries are selected from [anomalyco/models.dev](https://github.com/anomalyco/models.dev), an MIT-licensed community-maintained catalog used by OpenCode. Veasel pins the source revision to [${selected.source.commit}](${selected.source.repository}/tree/${selected.source.commit}); the selected base URLs, credential variable names, and documentation links are checked into tools/provider-catalog/providers.json. Refreshes preserve endpoint and credential mappings already shipped by Veasel, and keep removed upstream IDs as curated presets; change those connection values only through a reviewed catalog update. The V source and this page are generated from that file. No Models.dev network request, Node runtime, or other provider package is needed by Veasel after compilation. HTTPS provider requests validate server certificates against the operating system CA bundle; set SSL_CERT_FILE to use a custom PEM bundle. Windows uses the system certificate store.\n\nThe Models.dev selection filter requires its OpenAI-compatible adapter marker, an HTTPS API base URL without query credentials or templates, exactly one credential variable, and a documentation URL. Presets are not live-availability guarantees; endpoint access, account eligibility, model IDs, regional settings, and tool support depend on each provider. The openai-compatible preset remains available for custom endpoints. Local presets target loopback by default. Meta's live catalog also contains image-generation, transcription, and segmentation models that are not text-and-tool chat models. Veasel therefore offers the Muse Wonder and Muse Spark families in the coding-agent picker and leaves the incompatible families out. The documented coding choices include Muse Wonder 1.0 and Muse Spark 1.3. Veasel sends text and tool schemas and exposes a per-provider output-token budget from 16 to 131,072; zero uses Veasel's 4,096-token default except for Meta. Meta Responses counts reasoning tokens within this budget, so the Meta default omits \`max_output_tokens\`. Submitted conversation input is limited to 1 MiB (1,048,576 bytes) by default; \`VEASEL_MAX_CHAT_INPUT_BYTES\` may raise that byte budget up to 64 MiB for long-context providers (invalid values keep the default). Even raised, it is a byte budget, not a token budget: Veasel does not yet use Muse's full advertised 1,048,576-token context window.\n\nIf live model discovery fails, Veasel reports safe upstream status details without returning the provider response body or submitted credential. HTTP 401 means the provider rejected the key; 403 means the account or model lacks access; 404 usually means the configured endpoint has no model-list route, so enter a model ID manually; 429 means the provider rate-limited the request. Other failures keep a generic message to avoid exposing provider response data.\n\nOpenCode and OpenCode Go presets require an OpenCode Console API key; Veasel does not import the OpenCode CLI OAuth session. OpenCode Console free-tier chat models are limited to OpenCode itself, while Go is intended for compatible coding agents. Veasel sends OpenCode Go a stable session ID and its own User-Agent on each agent turn. See [OpenCode inference authentication](https://opencode.ai/v2/docs/console/api/inference) and [OpenCode Go integration requirements](https://opencode.ai/v2/docs/console/go/).\n\n| Provider | ID | Protocol used by Veasel | Default API endpoint | Credential | Reference |\n|---|---|---|---|---|---|\n${rows}\n`
}

async function renderOpenAPI() {
  const yaml = await readFile(openapiPath, "utf8")
  const providers = [...selected.providers].sort((a, b) => a.id.localeCompare(b.id))
  const replaceEnum = (source, key, nextKey) => {
    const marker = `        ${key}:\n          type: string\n          enum:\n`
    const start = source.indexOf(marker)
    const end = source.indexOf(`        ${nextKey}:`, start + marker.length)
    if (start < 0 || end < 0 || source.indexOf(marker, start + marker.length) >= 0) {
      throw new Error(`could not find the unique OpenAPI enum for ${key}`)
    }
    const entries = providers.map((provider) => `            - ${provider.id}\n`).join("")
    return `${source.slice(0, start + marker.length)}${entries}${source.slice(end)}`
  }
  return replaceEnum(replaceEnum(yaml, "provider", "model"), "active_provider", "profiles")
}

validate()
const outputs = [
  [outputPath, renderV()],
  [docsPath, renderDocs()],
  [openapiPath, await renderOpenAPI()],
]
if (process.argv.includes("--check")) {
  for (const [filename, expected] of outputs) {
    const actual = await readFile(filename, "utf8").catch(() => "")
    if (actual !== expected) {
      console.error(`${path.relative(root, filename)} is stale; run node tools/provider-catalog/generate.mjs`)
      process.exitCode = 1
    }
  }
} else {
  for (const [filename, content] of outputs) await writeFile(filename, content)
}
